<?php require 'includes/db.php';require 'includes/auth.php';require_login();$pdo=db();$cart=$_SESSION['cart']??[];if(!$cart){header('Location: cart.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$address=trim($_POST['address']??'');if(strlen($address)<10)$error='Enter a complete shipping address.';else{try{$pdo->beginTransaction();$items=[];$total=0;foreach($cart as $id=>$q){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch();if(!$p||$q>$p['stock'])throw new Exception('An item is unavailable or exceeds stock.');$items[]=[$p,$q];$total+=$p['price']*$q;}$s=$pdo->prepare('INSERT INTO orders(user_id,total,shipping_address) VALUES(?,?,?)');$s->execute([user_id(),$total,$address]);$oid=(int)$pdo->lastInsertId();foreach($items as [$p,$q]){$pdo->prepare('INSERT INTO order_items(order_id,product_id,quantity,price) VALUES(?,?,?,?)')->execute([$oid,$p['id'],$q,$p['price']]);$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$q,$p['id']]);}$pdo->commit();unset($_SESSION['cart']);header('Location: orders.php?placed=1');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}}require 'includes/header.php';?><div class="form-card"><h1>Checkout</h1><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Shipping address<textarea name="address" rows="5" required></textarea></label><button class="btn">Place Order</button></form><p class="muted">Demo checkout only. No online payment processing is included.</p></div><?php require 'includes/footer.php';?>